import json,pathlib,sys
e=json.loads(pathlib.Path(sys.argv[1]).read_bytes()); p=pathlib.Path(e['stdout']); ids=set(); malformed=[]
for n,line in enumerate(p.read_bytes().splitlines() if p.exists() else [],1):
 try:
  event=json.loads(line)
  if event.get('type')=='thread.started': ids.add(event['thread_id'])
 except (ValueError,TypeError,KeyError): malformed.append(n)
c=pathlib.Path(e['completion'])
print(json.dumps({'entry':e,'thread_ids':sorted(ids),'malformed_lines':malformed,'completion':json.loads(c.read_bytes()) if c.exists() else None,'semantic_status':'NOT_INFERRED'},ensure_ascii=False))

